g(0)&=\widehat{g}(0)=1.\label{eqn: g3}
\end{align}

Let us briefly explain our strategy for the proof of Theorem~\ref{thm: g}. First, we observe that conditions \eqref{eqn: g1}--\eqref{eqn: g3} imply additional properties of the function $g$. Suppose that there exists a Schwartz function $g$ such that the conditions \eqref{eqn: g1}--\eqref{eqn: g3} hold. The Poisson summation formula states
\begin{equation}
 \sum_{\ell\in\Lambda_8}g(\ell)= \sum_{\ell\in\Lambda_8}\widehat{g}(\ell).
\end{equation}
Since $\|\ell\|\geq\sqrt{2}$ for all $\ell\in\Lambda_8\backslash\{0\}$, conditions \eqref{eqn: g1} and \eqref{eqn: g3} imply
\begin{equation}
  \sum_{\ell\in\Lambda_8}g(\ell)\leq g(0)=1.
\end{equation}
On the other hand, conditions \eqref{eqn: g2} and \eqref{eqn: g3} imply
\begin{equation}
  \sum_{\ell\in\Lambda_8}\widehat{g}(\ell)\geq \widehat{g}(0)=1.
\end{equation}
Therefore, we deduce that $g(\ell)=\widehat{g}(\ell)=0$ for all $\ell\in\Lambda_8\backslash\{0\}$. Moreover, the first derivatives $\frac{d}{dr}g(r)$ and $\frac{d}{dr}\widehat{g}(r)$ also vanish at all $\Lambda_8$-lattice points of length bigger than $\sqrt{2}$.

